import React from 'react';
import { Dropdown, Menu, Button, Radio, Checkbox, Input, Slider, Select, Space } from 'antd';
import { DownOutlined, DeleteOutlined, PlusOutlined } from '@ant-design/icons';
import { deleteFilter, getGroupFilterOptions } from '../utils/filterHelpers';
import { sources, getSourceByCodename } from '../data/sources';
import airlines from '../data/airlines_full';
import { airports } from '../data/airports';

const { Search } = Input;
const { Option } = Select;

const FilterPanel = ({
  // Filter states
  segmentFilter,
  setSegmentFilter,
  segmentSearchText,
  setSegmentSearchText,
  classFilter,
  setClassFilter,
  directFilter,
  setDirectFilter,
  sourceFilter,
  setSourceFilter,
  sourceSearchText,
  setSourceSearchText,
  airlinesFilter,
  setAirlinesFilter,
  airlinesSearchText,
  setAirlinesSearchText,
  pointsFilter,
  setPointsFilter,
  dateFilter,
  setDateFilter,
  dateSearchText,
  setDateSearchText,
  additionalFilters,
  setAdditionalFilters,
  groupFilters,
  setGroupFilters,
  segmentFilters,
  setSegmentFilters,
  originSearchText,
  setOriginSearchText,
  destSearchText,
  setDestSearchText,

  // Utility functions
  getUniqueSegments,
  getUniqueSources,
  getUniqueAirlines,
  getPointsRange,
  getUniqueDates,
  sortSegments,
  moveSegment,

  // Data
  flightData
}) => {

  // Render segments dropdown
  const renderSegmentsDropdown = () => {
    const segments = getUniqueSegments(flightData);

    // Filter segments based on search text
    const filteredSegments = segments.filter(segment => {
      if (!segmentSearchText) return true;
      return segment.toLowerCase().includes(segmentSearchText.toLowerCase());
    });

    // Sort segments based on the current order
    const sortedSegments = [...filteredSegments].sort(sortSegments);

    const menu = (
      <Menu className="segment-menu">
        <div className="filter-header">
          <Radio.Group 
            value={segmentFilter.mode} 
            onChange={e => setSegmentFilter({ ...segmentFilter, mode: e.target.value })}
          >
            <Radio value="include">Include</Radio>
            <Radio value="exclude">Exclude</Radio>
          </Radio.Group>
          <Search
            placeholder="Search segments"
            value={segmentSearchText}
            onChange={e => setSegmentSearchText(e.target.value)}
            style={{ width: 200, marginTop: 8 }}
          />
        </div>
        <Menu.Divider />
        <div className="segment-list">
          {sortedSegments.map(segment => {
            const isSelected = segmentFilter.segments.includes(segment);
            const [origin, dest] = segment.split('-');

            return (
              <Menu.Item key={segment} className="segment-item">
                <div className="segment-item-content">
                  <Checkbox
                    checked={isSelected}
                    onChange={() => {
                      const segments = isSelected
                        ? segmentFilter.segments.filter(s => s !== segment)
                        : [...segmentFilter.segments, segment];
                      setSegmentFilter({ ...segmentFilter, segments });
                    }}
                  >
                    {origin} → {dest}
                  </Checkbox>
                  <div className="segment-controls">
                    <Button 
                      type="text" 
                      size="small" 
                      icon={<span>↑</span>} 
                      onClick={() => moveSegment(segment, 'up')}
                    />
                    <Button 
                      type="text" 
                      size="small" 
                      icon={<span>↓</span>} 
                      onClick={() => moveSegment(segment, 'down')}
                    />
                  </div>
                </div>
              </Menu.Item>
            );
          })}
        </div>
      </Menu>
    );

    return (
      <Dropdown overlay={menu} trigger={['click']} overlayClassName="wide-dropdown">
        <Button className="filter-button">
          Segments {segmentFilter.segments.length > 0 && `(${segmentFilter.segments.length})`} <DownOutlined />
        </Button>
      </Dropdown>
    );
  };

  // Render class dropdown
  const renderClassDropdown = () => {
    const classOptions = [
      { code: 'Y', name: 'Economy' },
      { code: 'W', name: 'Premium Economy' },
      { code: 'J', name: 'Business' },
      { code: 'F', name: 'First' }
    ];

    const menu = (
      <Menu>
        {classOptions.map(option => (
          <Menu.Item key={option.code}>
            <Checkbox
              checked={classFilter.includes(option.code)}
              onChange={() => {
                const updatedClassFilter = classFilter.includes(option.code)
                  ? classFilter.filter(c => c !== option.code)
                  : [...classFilter, option.code];
                setClassFilter(updatedClassFilter);
              }}
            >
              {option.name}
            </Checkbox>
          </Menu.Item>
        ))}
        <Menu.Divider />
        <Menu.Item>
          <Checkbox
            checked={directFilter}
            onChange={e => setDirectFilter(e.target.checked)}
          >
            Direct Flights Only
          </Checkbox>
        </Menu.Item>
      </Menu>
    );

    return (
      <Dropdown overlay={menu} trigger={['click']}>
        <Button className="filter-button">
          Classes {classFilter.length > 0 && `(${classFilter.length})`} <DownOutlined />
        </Button>
      </Dropdown>
    );
  };

  // Render sources dropdown
  const renderSourcesDropdown = () => {
    const availableSources = getUniqueSources(flightData);

    // Filter sources based on search text
    const filteredSources = availableSources.filter(source => {
      if (!sourceSearchText) return true;

      const sourceInfo = getSourceByCodename(source);
      const sourceName = sourceInfo ? sourceInfo.name : source;

      return sourceName.toLowerCase().includes(sourceSearchText.toLowerCase()) ||
             source.toLowerCase().includes(sourceSearchText.toLowerCase());
    });

    const menu = (
      <Menu className="source-menu">
        <div className="filter-header">
          <Radio.Group 
            value={sourceFilter.mode} 
            onChange={e => setSourceFilter({ ...sourceFilter, mode: e.target.value })}
          >
            <Radio value="include">Include</Radio>
            <Radio value="exclude">Exclude</Radio>
          </Radio.Group>
          <Search
            placeholder="Search sources"
            value={sourceSearchText}
            onChange={e => setSourceSearchText(e.target.value)}
            style={{ width: 200, marginTop: 8 }}
          />
        </div>
        <Menu.Divider />
        <div className="source-list">
          {filteredSources.map(source => {
            const isSelected = sourceFilter.sources.includes(source);
            const sourceInfo = getSourceByCodename(source);
            const sourceName = sourceInfo ? sourceInfo.name : source;

            return (
              <Menu.Item key={source}>
                <Checkbox
                  checked={isSelected}
                  onChange={() => {
                    const sources = isSelected
                      ? sourceFilter.sources.filter(s => s !== source)
                      : [...sourceFilter.sources, source];
                    setSourceFilter({ ...sourceFilter, sources });
                  }}
                >
                  {sourceName}
                </Checkbox>
              </Menu.Item>
            );
          })}
        </div>
      </Menu>
    );

    return (
      <Dropdown overlay={menu} trigger={['click']}>
        <Button className="filter-button">
          Sources {sourceFilter.sources.length > 0 && `(${sourceFilter.sources.length})`} <DownOutlined />
        </Button>
      </Dropdown>
    );
  };

  // Render airlines dropdown
  const renderAirlinesDropdown = () => {
    const availableAirlines = getUniqueAirlines(flightData);

    // Filter airlines based on search text
    const filteredAirlines = availableAirlines.filter(airlineCode => {
      if (!airlinesSearchText) return true;

      const airline = airlines.find(a => a.iata === airlineCode);
      const airlineName = airline ? airline.name : airlineCode;

      return airlineName.toLowerCase().includes(airlinesSearchText.toLowerCase()) ||
             airlineCode.toLowerCase().includes(airlinesSearchText.toLowerCase());
    });

    const menu = (
      <Menu className="airlines-menu">
        <div className="filter-header">
          <Radio.Group 
            value={airlinesFilter.mode} 
            onChange={e => setAirlinesFilter({ ...airlinesFilter, mode: e.target.value })}
          >
            <Radio value="include">Include</Radio>
            <Radio value="exclude">Exclude</Radio>
          </Radio.Group>
          <Search
            placeholder="Search airlines"
            value={airlinesSearchText}
            onChange={e => setAirlinesSearchText(e.target.value)}
            style={{ width: 200, marginTop: 8 }}
          />
        </div>
        <Menu.Divider />
        <div className="airlines-list">
          {filteredAirlines.map(airlineCode => {
            const isSelected = airlinesFilter.airlines.includes(airlineCode);
            const airline = airlines.find(a => a.iata === airlineCode);
            const airlineName = airline ? airline.name : airlineCode;

            return (
              <Menu.Item key={airlineCode}>
                <Checkbox
                  checked={isSelected}
                  onChange={() => {
                    const updatedAirlines = isSelected
                      ? airlinesFilter.airlines.filter(a => a !== airlineCode)
                      : [...airlinesFilter.airlines, airlineCode];
                    setAirlinesFilter({ ...airlinesFilter, airlines: updatedAirlines });
                  }}
                >
                  {airlineCode} - {airlineName}
                </Checkbox>
              </Menu.Item>
            );
          })}
        </div>
      </Menu>
    );

    return (
      <Dropdown overlay={menu} trigger={['click']}>
        <Button className="filter-button">
          Airlines {airlinesFilter.airlines.length > 0 && `(${airlinesFilter.airlines.length})`} <DownOutlined />
        </Button>
      </Dropdown>
    );
  };

  // Render points/miles dropdown
  const renderPointsDropdown = () => {
    const [minPoints, maxPoints] = getPointsRange(flightData);

    const menu = (
      <Menu className="points-menu">
        <div className="points-slider-container">
          <div className="points-range-display">
            {pointsFilter ? `${pointsFilter[0].toLocaleString()} - ${pointsFilter[1].toLocaleString()}` : 'Any points'}
          </div>
          <Slider
            range
            min={minPoints}
            max={maxPoints}
            defaultValue={pointsFilter || [minPoints, maxPoints]}
            onChange={value => setPointsFilter(value)}
            style={{ width: 240 }}
          />
          <div className="points-range-labels">
            <span>{minPoints.toLocaleString()}</span>
            <span>{maxPoints.toLocaleString()}</span>
          </div>
          {pointsFilter && (
            <Button 
              type="link" 
              onClick={() => setPointsFilter(null)}
              style={{ padding: 0 }}
            >
              Reset
            </Button>
          )}
        </div>
      </Menu>
    );

    return (
      <Dropdown overlay={menu} trigger={['click']}>
        <Button className="filter-button">
          Points {pointsFilter && `(${pointsFilter[0].toLocaleString()} - ${pointsFilter[1].toLocaleString()})`} <DownOutlined />
        </Button>
      </Dropdown>
    );
  };

  // Add additional filter button
  const renderAddFilterButton = () => {
    const handleAddFilter = (type) => {
      // Generate a unique ID for the new filter
      const filterId = `filter-${Date.now()}`;

      // Add to additionalFilters array
      setAdditionalFilters([...additionalFilters, { id: filterId, type }]);

      // Initialize appropriate filter data based on type
      if (type === 'group') {
        setGroupFilters({
          ...groupFilters,
          [filterId]: {
            originFilter: { mode: 'group', include: true, group: null },
            destFilter: { mode: 'group', include: true, group: null }
          }
        });
      } else if (type === 'segment') {
        setSegmentFilters({
          ...segmentFilters,
          [filterId]: { mode: 'include', segments: [] }
        });
      }
    };

    const menu = (
      <Menu>
        <Menu.Item key="group" onClick={() => handleAddFilter('group')}>
          Add Group Filter
        </Menu.Item>
        <Menu.Item key="segment" onClick={() => handleAddFilter('segment')}>
          Add Segment Filter
        </Menu.Item>
      </Menu>
    );

    return (
      <Dropdown overlay={menu} trigger={['click']}>
        <Button type="primary" icon={<PlusOutlined />} className="add-filter-button">
          Add Filter
        </Button>
      </Dropdown>
    );
  };

  // Render additional filters that have been added
  const renderAdditionalFilters = () => {
    return additionalFilters.map(filter => {
      const filterId = filter.id;

      // Render a group-based filter
      if (filter.type === 'group') {
        return (
          <div key={filterId} className="additional-filter-container">
            <div className="filter-header">
              <span>Group Filter</span>
              <Button 
                type="text" 
                icon={<DeleteOutlined />}
                onClick={() => deleteFilter(
                  filterId, 
                  additionalFilters, 
                  setAdditionalFilters,
                  groupFilters,
                  setGroupFilters,
                  segmentFilters,
                  setSegmentFilters
                )}
              />
            </div>

            <div className="filter-body">
              <div className="filter-row">
                <div className="filter-label">Origin:</div>
                <div className="filter-inputs">
                  {renderOriginDropdown(filterId)}
                </div>
              </div>

              <div className="filter-row">
                <div className="filter-label">Destination:</div>
                <div className="filter-inputs">
                  {renderDestDropdown(filterId)}
                </div>
              </div>
            </div>
          </div>
        );
      }

      // Render a segment filter
      if (filter.type === 'segment') {
        return (
          <div key={filterId} className="additional-filter-container">
            <div className="filter-header">
              <span>Segment Filter</span>
              <Button 
                type="text" 
                icon={<DeleteOutlined />}
                onClick={() => deleteFilter(
                  filterId, 
                  additionalFilters, 
                  setAdditionalFilters,
                  groupFilters,
                  setGroupFilters,
                  segmentFilters,
                  setSegmentFilters
                )}
              />
            </div>

            <div className="filter-body">
              {renderSegmentsDropdownSimple(filterId)}
            </div>
          </div>
        );
      }

      return null;
    });
  };

  // Render origin dropdown for group filters
  const renderOriginDropdown = (filterId) => {
    const filter = groupFilters[filterId]?.originFilter || {};

    // Create options for the dropdowns
    const options = getGroupFilterOptions(airports);

    return (
      <div className="filter-controls">
        <Radio.Group 
          value={filter.include} 
          onChange={e => {
            setGroupFilters({
              ...groupFilters,
              [filterId]: {
                ...groupFilters[filterId],
                originFilter: {
                  ...filter,
                  include: e.target.value
                }
              }
            });
          }}
          style={{ marginRight: 8 }}
        >
          <Radio value={true}>Include</Radio>
          <Radio value={false}>Exclude</Radio>
        </Radio.Group>

        <Select
          style={{ width: 280 }}
          placeholder="Select origin"
          value={filter.mode === 'group' ? filter.group : filter.airport}
          onChange={(value, option) => {
            setGroupFilters({
              ...groupFilters,
              [filterId]: {
                ...groupFilters[filterId],
                originFilter: {
                  ...filter,
                  mode: option.type,
                  group: option.type === 'group' ? value : null,
                  airport: option.type === 'airport' ? value : null
                }
              }
            });
          }}
          showSearch
          filterOption={(input, option) =>
            option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
          }
        >
          {options.map(option => (
            <Option key={option.value} value={option.value} type={option.type}>
              {option.label}
            </Option>
          ))}
        </Select>
      </div>
    );
  };

  // Render destination dropdown for group filters
  const renderDestDropdown = (filterId) => {
    const filter = groupFilters[filterId]?.destFilter || {};

    // Create options for the dropdowns
    const options = getGroupFilterOptions(airports);

    return (
      <div className="filter-controls">
        <Radio.Group 
          value={filter.include} 
          onChange={e => {
            setGroupFilters({
              ...groupFilters,
              [filterId]: {
                ...groupFilters[filterId],
                destFilter: {
                  ...filter,
                  include: e.target.value
                }
              }
            });
          }}
          style={{ marginRight: 8 }}
        >
          <Radio value={true}>Include</Radio>
          <Radio value={false}>Exclude</Radio>
        </Radio.Group>

        <Select
          style={{ width: 280 }}
          placeholder="Select destination"
          value={filter.mode === 'group' ? filter.group : filter.airport}
          onChange={(value, option) => {
            setGroupFilters({
              ...groupFilters,
              [filterId]: {
                ...groupFilters[filterId],
                destFilter: {
                  ...filter,
                  mode: option.type,
                  group: option.type === 'group' ? value : null,
                  airport: option.type === 'airport' ? value : null
                }
              }
            });
          }}
          showSearch
          filterOption={(input, option) =>
            option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
          }
        >
          {options.map(option => (
            <Option key={option.value} value={option.value} type={option.type}>
              {option.label}
            </Option>
          ))}
        </Select>
      </div>
    );
  };

  // Render segment dropdown for segment-type filters
  const renderSegmentsDropdownSimple = (filterId) => {
    const filter = segmentFilters[filterId] || { mode: 'include', segments: [] };
    const segments = getUniqueSegments(flightData);

    return (
      <div className="segment-filter-controls">
        <Radio.Group 
          value={filter.mode} 
          onChange={e => {
            setSegmentFilters({
              ...segmentFilters,
              [filterId]: {
                ...filter,
                mode: e.target.value
              }
            });
          }}
          style={{ marginBottom: 8 }}
        >
          <Radio value="include">Include</Radio>
          <Radio value="exclude">Exclude</Radio>
        </Radio.Group>

        <Select
          mode="multiple"
          style={{ width: '100%' }}
          placeholder="Select segments"
          value={filter.segments}
          onChange={value => {
            setSegmentFilters({
              ...segmentFilters,
              [filterId]: {
                ...filter,
                segments: value
              }
            });
          }}
          optionFilterProp="children"
          filterOption={(input, option) =>
            option.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
          }
        >
          {segments.map(segment => {
            const [origin, dest] = segment.split('-');
            return (
              <Option key={segment} value={segment}>
                {origin} → {dest}
              </Option>
            );
          })}
        </Select>
      </div>
    );
  };

  return (
    <div className="filter-panel">
      <div className="filter-buttons">
        {renderSegmentsDropdown()}
        {renderClassDropdown()}
        {renderSourcesDropdown()}
        {renderAirlinesDropdown()}
        {renderPointsDropdown()}
        {renderAddFilterButton()}
      </div>

      <div className="additional-filters">
        {renderAdditionalFilters()}
      </div>

      {/* Active Filters Display */}
      {((segmentFilter.segments.length > 0) || 
        (classFilter.length > 0) || 
        directFilter || 
        (sourceFilter.sources.length > 0) || 
        (airlinesFilter.airlines.length > 0) || 
        pointsFilter || 
        (dateFilter.length > 0) ||
        (additionalFilters.length > 0)) && (
        <div className="active-filters">
          <div className="active-filters-header">Active Filters:</div>
          <div className="active-filters-list">
            {/* Display active filters here */}
          </div>

          <Button 
            type="link" 
            onClick={() => {
              // Reset all filters
              setSegmentFilter({ mode: 'include', segments: [] });
              setClassFilter([]);
              setDirectFilter(false);
              setSourceFilter({ mode: 'include', sources: [] });
              setAirlinesFilter({ mode: 'include', airlines: [] });
              setPointsFilter(null);
              setDateFilter([]);
              setAdditionalFilters([]);
              setGroupFilters({});
              setSegmentFilters({});
            }}
          >
            Clear All Filters
          </Button>
        </div>
      )}
    </div>
  );
};

export default FilterPanel;
